    # 7 - (401) POST:/api/v1/agents/{agent_id}/instance/{instance_id}/offline
    # Found 7 potential faults. Type-codes: 101, 205
    @timeout_decorator.timeout(60)
    def test_61_post_on_offline_showsFaults_101_205(self):
        
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"email\" : \"viewer\", " + \
            " \"password\" : \"V1ewer-Bamf-Thesis-2026\" " + \
            " } "
        res_viewer = requests \
                .post("http://localhost:8211/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_viewer =  res_viewer.json()["token"]
        
        auth_viewer = "Bearer " + token_viewer
        headers = {}
        headers["content-type"] = "application/json"
